import{_ as i,c as t,o as s,ae as a}from"./chunks/framework.DMK_uHmU.js";const d=JSON.parse('{"title":"Feature Settings Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Global-Settings/features.md","filePath":"Administration/Manage/Global-Settings/features.md"}'),n={name:"Administration/Manage/Global-Settings/features.md"};function l(o,e,r,u,c,g){return s(),t("div",null,e[0]||(e[0]=[a('<h1 id="feature-settings-configuration-guide" tabindex="-1">Feature Settings Configuration Guide <a class="header-anchor" href="#feature-settings-configuration-guide" aria-label="Permalink to &quot;Feature Settings Configuration Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#feature-settings-configuration-guide">Feature Settings Configuration Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-feature-settings">Accessing Feature Settings</a></li><li><a href="#ai-assistant-feature-settings">AI Assistant Feature Settings</a><ul><li><a href="#audio-support">Audio Support</a></li><li><a href="#featured-content-row">Featured Content Row</a></li><li><a href="#shortcuts-menu--actions">Shortcuts Menu &amp; Actions</a></li><li><a href="#multiple-knowledge-bases">Multiple Knowledge Bases</a></li><li><a href="#pdf-viewer">PDF Viewer</a></li><li><a href="#topics-menu-selector">Topics Menu Selector</a></li></ul></li><li><a href="#messaging-configuration">Messaging Configuration</a><ul><li><a href="#welcome-message">Welcome Message</a></li><li><a href="#help-menu-message">Help Menu Message</a></li></ul></li><li><a href="#feature-interactions">Feature Interactions</a></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Feature Settings component allows administrators to configure which features are available in the platform and customize the user experience. This interface provides toggles for enabling or disabling specific functionality and customizing system messages that users see throughout the application.</p><h2 id="accessing-feature-settings" tabindex="-1">Accessing Feature Settings <a class="header-anchor" href="#accessing-feature-settings" aria-label="Permalink to &quot;Accessing Feature Settings&quot;">​</a></h2><p>The Feature Settings component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to the Tenant Settings section in the administration interface and select the &quot;Features&quot; tab.</p><h2 id="ai-assistant-feature-settings" tabindex="-1">AI Assistant Feature Settings <a class="header-anchor" href="#ai-assistant-feature-settings" aria-label="Permalink to &quot;AI Assistant Feature Settings&quot;">​</a></h2><p>The AI Assistant Feature Settings section controls the availability of specific capabilities within the AI Assistant interface. Each feature can be independently enabled or disabled to tailor the experience to your organization&#39;s needs.</p><h3 id="audio-support" tabindex="-1">Audio Support <a class="header-anchor" href="#audio-support" aria-label="Permalink to &quot;Audio Support&quot;">​</a></h3><ul><li><strong>Setting</strong>: Enable Audio Support</li><li><strong>Default</strong>: Enabled (ON)</li><li><strong>Description</strong>: When enabled, allows users to: <ul><li>Listen to AI responses through text-to-speech</li><li>Input queries using voice recognition</li><li>Control audio playback speed and volume</li></ul></li><li><strong>Use Cases</strong>: <ul><li>Accessibility for users with visual impairments</li><li>Hands-free operation in certain environments</li><li>Multi-tasking scenarios where reading is impractical</li></ul></li></ul><h3 id="featured-content-row" tabindex="-1">Featured Content Row <a class="header-anchor" href="#featured-content-row" aria-label="Permalink to &quot;Featured Content Row&quot;">​</a></h3><ul><li><strong>Setting</strong>: Enable Featured Content Row</li><li><strong>Default</strong>: Enabled (ON)</li><li><strong>Description</strong>: When enabled: <ul><li>Displays a scrollable row of featured content cards on the home screen</li><li>Shows curated content selected by administrators</li><li>Provides quick access to important resources</li></ul></li><li><strong>Use Cases</strong>: <ul><li>Highlighting new or important content</li><li>Promoting specific resources</li><li>Creating a guided experience for new users</li></ul></li></ul><h3 id="shortcuts-menu-actions" tabindex="-1">Shortcuts Menu &amp; Actions <a class="header-anchor" href="#shortcuts-menu-actions" aria-label="Permalink to &quot;Shortcuts Menu &amp; Actions&quot;">​</a></h3><ul><li><strong>Setting</strong>: Enable Shortcuts Menu &amp; Actions</li><li><strong>Default</strong>: Enabled (ON)</li><li><strong>Description</strong>: When enabled: <ul><li>Shows a floating shortcuts button in the interface</li><li>Provides quick access to common actions and queries</li><li>Allows administrators to define custom shortcuts</li></ul></li><li><strong>Use Cases</strong>: <ul><li>Streamlining common tasks</li><li>Guiding users to recommended actions</li><li>Reducing typing for frequent queries</li></ul></li></ul><h3 id="multiple-knowledge-bases" tabindex="-1">Multiple Knowledge Bases <a class="header-anchor" href="#multiple-knowledge-bases" aria-label="Permalink to &quot;Multiple Knowledge Bases&quot;">​</a></h3><ul><li><strong>Setting</strong>: Enable Multiple Knowledge Bases</li><li><strong>Default</strong>: Enabled (ON)</li><li><strong>Description</strong>: When enabled: <ul><li>Allows users to select which knowledge bases to include in their queries</li><li>Provides a knowledge base selector in the interface</li><li>Supports combining multiple knowledge sources in a single conversation</li></ul></li><li><strong>Use Cases</strong>: <ul><li>Departmental knowledge separation</li><li>Topic-specific searching</li><li>Reducing noise in search results</li></ul></li></ul><h3 id="pdf-viewer" tabindex="-1">PDF Viewer <a class="header-anchor" href="#pdf-viewer" aria-label="Permalink to &quot;PDF Viewer&quot;">​</a></h3><ul><li><strong>Setting</strong>: Enable New PDF Viewer</li><li><strong>Default</strong>: Enabled (ON)</li><li><strong>Description</strong>: When enabled: <ul><li>Uses the enhanced PDF viewing experience</li><li>Provides advanced navigation and search within PDFs</li><li>Supports annotations and highlights</li></ul></li><li><strong>Use Cases</strong>: <ul><li>Detailed document review</li><li>Research scenarios requiring document analysis</li><li>Training contexts requiring reference material</li></ul></li></ul><h3 id="topics-menu-selector" tabindex="-1">Topics Menu Selector <a class="header-anchor" href="#topics-menu-selector" aria-label="Permalink to &quot;Topics Menu Selector&quot;">​</a></h3><ul><li><strong>Setting</strong>: Enable Topics Menu Selector</li><li><strong>Default</strong>: Enabled (ON)</li><li><strong>Description</strong>: When enabled: <ul><li>Shows a categorized menu of available topics</li><li>Allows users to browse content by subject area</li><li>Provides structured navigation through available information</li></ul></li><li><strong>Use Cases</strong>: <ul><li>Helping users discover relevant content</li><li>Organizing information by department or function</li><li>Providing a browsing alternative to search</li></ul></li></ul><h2 id="messaging-configuration" tabindex="-1">Messaging Configuration <a class="header-anchor" href="#messaging-configuration" aria-label="Permalink to &quot;Messaging Configuration&quot;">​</a></h2><p>The Messaging section allows customization of the text messages displayed to users in key areas of the application.</p><h3 id="welcome-message" tabindex="-1">Welcome Message <a class="header-anchor" href="#welcome-message" aria-label="Permalink to &quot;Welcome Message&quot;">​</a></h3><ul><li><strong>Field</strong>: Home screen landing page welcome message</li><li><strong>Default</strong>: &quot;To start click on the shortcuts icon or type a question below&quot;</li><li><strong>Purpose</strong>: This message appears prominently on the home screen when users first access the system</li><li><strong>Guidelines</strong>: <ul><li>Keep it concise (1-2 sentences)</li><li>Include clear instructions for getting started</li><li>Maintain a friendly, helpful tone</li><li>Consider including your organization&#39;s name for personalization</li><li>Maximum recommended length: 120 characters</li></ul></li></ul><h3 id="help-menu-message" tabindex="-1">Help Menu Message <a class="header-anchor" href="#help-menu-message" aria-label="Permalink to &quot;Help Menu Message&quot;">​</a></h3><ul><li><strong>Field</strong>: Home screen help menu message</li><li><strong>Default</strong>: &quot;There are many ways to get help. You can type a question, click on the shortcuts icon, or click on the topics icon to find the information you need.&quot;</li><li><strong>Purpose</strong>: This message appears in the help menu when users click the help icon</li><li><strong>Guidelines</strong>: <ul><li>Be more comprehensive than the welcome message</li><li>Include multiple options for getting assistance</li><li>Reference available features (shortcuts, topics)</li><li>Maximum recommended length: 250 characters</li></ul></li></ul><h2 id="feature-interactions" tabindex="-1">Feature Interactions <a class="header-anchor" href="#feature-interactions" aria-label="Permalink to &quot;Feature Interactions&quot;">​</a></h2><p>Understanding how features work together is important for creating a cohesive user experience:</p><ol><li><p><strong>Topics and Shortcuts Integration</strong></p><ul><li>When both Topics Menu and Shortcuts are enabled, they provide complementary navigation methods</li><li>Topics offers structured browsing while shortcuts provide quick access</li><li>Consider creating shortcuts that align with important topics</li></ul></li><li><p><strong>Audio Support and PDF Viewer</strong></p><ul><li>When both are enabled, users can have PDF content read aloud</li><li>Consider accessibility implications when disabling either feature</li></ul></li><li><p><strong>Multiple Knowledge Bases and Featured Content</strong></p><ul><li>Featured content can draw from all enabled knowledge bases</li><li>Users with access to multiple knowledge bases will see combined results</li></ul></li><li><p><strong>Welcome Message and Enabled Features</strong></p><ul><li>Ensure your welcome message references only features that are enabled</li><li>Update the message if you disable referenced features like shortcuts</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For optimal feature configuration:</p><ol><li><p><strong>Consistent Experience</strong></p><ul><li>Enable a cohesive set of features that work well together</li><li>Avoid confusing users by referencing disabled features in help text</li><li>Consider user workflow when deciding which features to enable</li></ul></li><li><p><strong>Message Customization</strong></p><ul><li>Personalize messages with your organization&#39;s name</li><li>Reference specific help resources relevant to your users</li><li>Keep language simple and direct</li><li>Ensure messages are appropriate for all user roles</li></ul></li><li><p><strong>Feature Selection</strong></p><ul><li>Consider your users&#39; technical proficiency when enabling features</li><li>Start with core features for new deployments</li><li>Gradually introduce advanced features as users become comfortable</li><li>Get feedback on which features are most valuable</li></ul></li><li><p><strong>Performance Considerations</strong></p><ul><li>Enabling all features may impact performance on some devices</li><li>Multiple Knowledge Bases can increase query complexity</li><li>Audio features require additional browser capabilities</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Features appear enabled but aren&#39;t visible to users</p><ul><li>Check user role permissions in the User Management section</li><li>Verify that the feature is supported in the user&#39;s browser</li><li>Check for conflicts with other system settings</li></ul><p><strong>Issue</strong>: Custom messages not appearing</p><ul><li>Ensure messages are saved after editing</li><li>Check character limits (system may truncate very long messages)</li><li>Verify that the correct tenant settings are active</li></ul><p><strong>Issue</strong>: Audio features not working</p><ul><li>Verify browser compatibility (requires modern browsers)</li><li>Check user device microphone and speaker permissions</li><li>Ensure network connectivity for text-to-speech services</li></ul><p><strong>Issue</strong>: Featured content not displaying</p><ul><li>Check that content has been marked as &quot;featured&quot; in the content manager</li><li>Verify user has permission to view the featured content</li><li>Ensure featured content exists in knowledge bases the user can access</li></ul><p><strong>Issue</strong>: PDF viewer showing old version</p><ul><li>Clear browser cache</li><li>Check if users need to refresh their application</li><li>Verify the setting has been properly saved</li></ul><hr><p>For additional assistance with feature configuration, please contact your system administrator or refer to the platform documentation.</p>',48)]))}const p=i(n,[["render",l]]);export{d as __pageData,p as default};
